#include <bits/stdc++.h>
using namespace std;
class Solution {public:vector<int> minEdgeReversals(int n,vector<vector<int>>& edges){vector<vector<pair<int,int>>> g(n);for(auto&e:edges){g[e[0]].push_back({e[1],0});g[e[1]].push_back({e[0],1});}vector<int> par(n,-1),order={0},ans(n);par[0]=0;for(int i=0;i<(int)order.size();++i){int u=order[i];for(auto [v,c]:g[u])if(v!=par[u]){par[v]=u;ans[0]+=c;order.push_back(v);}}for(int u:order)for(auto [v,c]:g[u])if(v!=par[u])ans[v]=ans[u]+(c==0?1:-1);return ans;}};
